{
  "items": [
    {
      "title": "European Values Study 2017: Integrated Dataset (EVS 2017)",
      "url_or_doi": "https://doi.org/10.4232/1.13897",
      "justification": "This dataset provides cross-national survey data collected between 2017 and 2021 across European countries including Albania, Armenia, Austria, Azerbaijan, Belarus, Bosnia and Herzegovina, Bulgaria, Croatia, Czech Republic, Denmark, Estonia, Finland, France, Georgia, Germany, Great Britain, Hungary, Iceland, Italy, Latvia, Lithuania, Montenegro, Netherlands, North Macedonia, Norway, Poland, Romania, Russian Federation, Serbia, Slovakia, Slovenia, Spain, Sweden, Switzerland, Portugal, and Ukraine. It covers core topics such as labor and employment, cultural and national identity, religion and values, family life and marriage, political behavior and attitudes, gender roles, environment and conservation, democracy, and social trust."
    },
    {
      "title": "Joint EVS/WVS 2017-2022 Dataset",
      "url_or_doi": "https://doi.org/10.4232/1.14320",
      "justification": "Harmonizes the fifth wave of the European Values Study (EVS) and the seventh wave of the World Values Survey (WVS) for 2017–2022. It contains a standardized common core of variables across European and global societies covering attitudes toward family, work, religion, politics, democracy, national identity, environment, and social trust alongside comprehensive sociodemographic indicators."
    },
    {
      "title": "World Values Survey Wave 7 (2017-2022) Country-Pooled Datafile",
      "url_or_doi": "https://doi.org/10.14281/18241.24",
      "justification": "Contains cross-national survey data from WVS Wave 7 (2017–2022) covering European and global societies. Key themes include cultural identity, social trust, political participation, religious values, family norms, gender roles, and environmental attitudes with harmonized demographic measures."
    },
    {
      "title": "European Social Survey Data Portal",
      "url_or_doi": "https://www.europeansocialsurvey.org/data",
      "justification": "Offers cross-national longitudinal European survey data across multiple rounds in the 2010s and 2020s (Rounds 5 to 10+). It features core modules on public attitudes regarding politics, democracy, social trust, immigration, human values, and environment, complemented by rotating modules and rich demographics."
    }
  ]
}
```
